"""Anima Owner 生命控制台。

页面不依赖外部 CDN，所有接口数据先翻译成业务语义再展示。原始响应不会直接
铺在页面上；Owner 看到的是状态、原因、下一步动作与审批证据。
"""

DASHBOARD_HTML = r"""<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#151226">
<title>Anima · 生命控制台</title>
<style>
:root{
  color-scheme:dark;
  --bg:#11101e;--surface:#1b172b;--surface-2:#241d36;--surface-3:#2d2441;
  --ink:#fff9f0;--muted:#bdb2c9;--line:#493c5b;--lime:#bdf46d;--pink:#ff9fc8;
  --blue:#91c7ff;--amber:#ffd27b;--red:#ff7d91;--paper:#fff4da;--paper-ink:#251c30;
  --shadow-sm:0 8px 24px #0806114d;--shadow-md:10px 12px 0 #090711;
  --radius-sm:12px;--radius-md:18px;--radius-lg:26px;
  --space-xs:6px;--space-sm:10px;--space-md:16px;--space-lg:24px;--space-xl:36px;
  --ease:cubic-bezier(.22,1,.36,1);--z-sticky:20;--z-scrim:30;--z-nav:40;--z-toast:60;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;min-height:100vh;background:
  radial-gradient(900px 520px at 8% -10%,#6f4d7952,transparent 68%),
  radial-gradient(800px 480px at 105% 5%,#24526a46,transparent 65%),var(--bg);
  color:var(--ink);font:14px/1.55 system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif}
body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.28;background-image:
  linear-gradient(#fff08 1px,transparent 1px),linear-gradient(90deg,#fff08 1px,transparent 1px);
  background-size:30px 30px;mask-image:linear-gradient(#0008,transparent 78%);animation:drift 18s linear infinite}
@keyframes drift{to{transform:translate3d(30px,30px,0)}}
button,input,select,textarea{font:inherit}button{color:inherit}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{
  outline:3px solid #91c7ff80;outline-offset:3px}
.app{width:min(1560px,100%);margin:auto;padding:clamp(14px,2.2vw,32px)}
.topbar{display:flex;align-items:center;gap:var(--space-md);margin-bottom:var(--space-lg)}
.brand{display:flex;align-items:center;gap:13px;min-width:max-content}.brand-mark{position:relative;display:grid;place-items:center;
  width:54px;height:54px;border-radius:19px 19px 19px 6px;background:var(--lime);color:#1c221a;
  box-shadow:7px 8px 0 #755079;transform:rotate(-3deg);font:900 28px Georgia,serif}
.brand-mark:after{content:"";position:absolute;width:9px;height:9px;border-radius:50%;background:#ff6fa4;right:11px;top:17px}
.brand strong{display:block;font-size:clamp(23px,3vw,32px);line-height:1;letter-spacing:-1px}.brand span{color:var(--muted);font-size:12px}
.topline{height:1px;flex:1;max-width:280px;background:repeating-linear-gradient(90deg,var(--lime) 0 7px,transparent 7px 13px)}
.top-actions{margin-left:auto;display:flex;align-items:center;gap:var(--space-sm)}.updated{color:var(--muted);font-size:12px}
.button{border:1px solid #69567e;background:#352a49;border-radius:var(--radius-sm);padding:9px 13px;cursor:pointer;font-weight:750;
  transition:transform .16s var(--ease),filter .16s,box-shadow .16s}.button:hover{transform:translateY(-2px);filter:brightness(1.12);box-shadow:0 5px 0 #090711}.button:active{transform:translateY(1px);box-shadow:none}
.button.primary{border:0;background:var(--lime);color:#182115}.button.soft{background:#2b253d}.button.danger{background:#612b40;border-color:#9b435f}.button.small{padding:7px 10px;font-size:12px}.button[disabled]{opacity:.45;cursor:not-allowed;transform:none;box-shadow:none}
.hamburger{display:none;width:42px;height:42px;padding:0;place-items:center;font-size:20px}
.layout{display:grid;grid-template-columns:248px minmax(0,1fr);gap:var(--space-lg);align-items:start}
.sidebar{position:sticky;top:18px;z-index:var(--z-sticky);padding:12px;border:1px solid #5b486d;border-radius:var(--radius-lg);
  background:#181426e8;backdrop-filter:blur(18px);box-shadow:var(--shadow-md)}
.nav-title{padding:8px 11px 13px;color:#9485a2;font:700 10px ui-monospace,Consolas,monospace;letter-spacing:1.1px;text-transform:uppercase}
.nav-button{display:flex;align-items:center;gap:11px;width:100%;padding:13px 12px;border:0;border-radius:13px;background:transparent;color:#c5b8ce;cursor:pointer;text-align:left;font-weight:750;transition:transform .2s var(--ease),background .2s,color .2s}
.nav-button .index{display:grid;place-items:center;width:24px;height:24px;border-radius:8px;background:#342b48;color:#bdaece;font:700 11px ui-monospace,Consolas,monospace}
.nav-button:hover{transform:translateX(4px);background:#282137}.nav-button.active{background:var(--paper);color:var(--paper-ink);box-shadow:3px 4px 0 #b46a90}.nav-button.active .index{background:#251d31;color:var(--lime)}
.nav-foot{margin-top:12px;padding:14px 12px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.nav-foot b{display:block;color:var(--lime);margin-bottom:3px}
.content{min-width:0}.view{display:none}.view.active{display:block;animation:viewIn .42s var(--ease)}@keyframes viewIn{from{opacity:0;transform:translateY(14px) scale(.992)}to{opacity:1;transform:none}}
.hero{position:relative;display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:20px;align-items:center;overflow:hidden;
  min-height:176px;padding:clamp(20px,3vw,32px);border-radius:var(--radius-lg);background:linear-gradient(120deg,#f1ddbd,#fff5df 55%,#c7f47f 155%);color:var(--paper-ink);box-shadow:10px 12px 0 #75517a;margin-bottom:var(--space-lg)}
.hero:after{content:"";position:absolute;width:250px;height:250px;right:-105px;top:-125px;border:25px solid #271e3440;border-radius:50%;box-shadow:0 0 0 18px #271e3414}
.life-core{position:relative;width:86px;height:86px;border-radius:31px 31px 31px 9px;background:#251e36;box-shadow:inset 0 0 0 1px #fff2;display:grid;place-items:center;color:var(--lime);font:900 34px Georgia,serif;animation:breathe 3.2s ease-in-out infinite}
.life-core:after{content:"";position:absolute;inset:-8px;border:1px solid #251e3633;border-radius:37px;animation:halo 3.2s ease-out infinite}@keyframes breathe{50%{transform:translateY(-3px);box-shadow:0 13px 25px #6d4d7455,inset 0 0 0 1px #fff2}}@keyframes halo{70%,100%{transform:scale(1.12);opacity:0}}
.hero h1{margin:0 0 8px;font-size:clamp(25px,4vw,44px);line-height:1.05;letter-spacing:-1.7px}.hero p{margin:0;max-width:700px;color:#594c60;font-weight:650}.hero-actions{position:relative;z-index:1;display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.hero .button{background:#251e36;border:0}.hero .button.primary{background:var(--lime)}
.section-head{display:flex;justify-content:space-between;align-items:end;gap:16px;margin:var(--space-xl) 0 var(--space-md)}.section-head:first-child{margin-top:0}.section-head h1,.section-head h2{margin:0;font-size:clamp(21px,3vw,30px);letter-spacing:-.7px}.section-head p{margin:5px 0 0;color:var(--muted);max-width:760px}.eyebrow{display:block;color:var(--lime);font:800 10px ui-monospace,Consolas,monospace;letter-spacing:1.4px;text-transform:uppercase;margin-bottom:5px}
.summary-strip{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:var(--space-lg)}
.signal{min-width:0;padding:16px;border:1px solid var(--line);border-radius:var(--radius-md);background:#1b172bd9;box-shadow:var(--shadow-sm);transition:transform .2s var(--ease),border-color .2s}.signal:hover{transform:translateY(-3px);border-color:#806896}.signal .label{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:12px}.signal .value{display:block;margin-top:8px;font-size:20px;font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.signal .hint{color:#9f92ab;font-size:11px}.status-dot{width:8px;height:8px;border-radius:50%;background:var(--lime);box-shadow:0 0 12px currentColor}.status-dot.warn{background:var(--amber)}.status-dot.bad{background:var(--red)}
.workspace{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(300px,.7fr);gap:var(--space-lg)}
.panel{min-width:0;border:1px solid var(--line);border-radius:var(--radius-md);background:linear-gradient(140deg,#211b33,#181426);box-shadow:var(--shadow-sm);padding:clamp(16px,2.2vw,22px)}
.panel + .panel{margin-top:var(--space-md)}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}.panel h2,.panel h3{margin:0}.panel h2{font-size:17px}.panel h3{font-size:14px}.panel-note{color:var(--muted);font-size:12px}.panel-accent{border-color:#6f587e;background:linear-gradient(140deg,#29203a,#1d172b)}
.module-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}
.module{position:relative;overflow:hidden;border:1px solid #493c5c;border-radius:15px;background:#181425;padding:15px;min-height:142px;transition:transform .2s var(--ease),border-color .2s}.module:hover{transform:translateY(-3px);border-color:#846b96}.module:after{content:"";position:absolute;width:76px;height:76px;border:1px solid #fff1;border-radius:50%;right:-30px;bottom:-34px}.module-top{display:flex;justify-content:space-between;gap:10px}.module h3{font-size:14px}.state{display:inline-flex;align-items:center;gap:5px;border-radius:99px;padding:4px 8px;background:#31462b;color:#dfffb8;font-size:10px;font-weight:800}.state.ready{background:#263d55;color:#bfe0ff}.state.degraded,.state.stopped{background:#59472b;color:#ffe0a2}.state.disabled{background:#393344;color:#ada2b7}.state.bad{background:#5b2938;color:#ffbdc8}.module p{min-height:42px;margin:10px 0;color:var(--muted);font-size:12px}.metric-list{display:flex;flex-wrap:wrap;gap:6px}.metric-chip{padding:4px 7px;border-radius:7px;background:#2a233a;color:#c9bdd3;font-size:10px}.metric-chip b{color:var(--ink);margin-left:3px}
.feed,.stack{display:grid;gap:9px}.feed{max-height:780px;overflow:auto;padding-right:4px}.feed-item,.item{display:flex;gap:12px;align-items:flex-start;padding:13px;border:1px solid #413550;border-radius:13px;background:#181424}.feed-mark{display:grid;place-items:center;width:30px;height:30px;flex:0 0 auto;border-radius:10px;background:#302740;color:var(--pink);font:800 11px ui-monospace,Consolas,monospace}.feed-item b,.item b{display:block}.feed-item p,.item p{margin:3px 0 0;color:var(--muted);font-size:12px;overflow-wrap:anywhere}.item{justify-content:space-between}.item-main{min-width:0}.item-actions{display:flex;flex-wrap:wrap;gap:6px;justify-content:flex-end}.chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.chip{border-radius:99px;background:#30273f;color:#ccbed7;padding:4px 8px;font-size:10px}.chip.lime{background:#34492c;color:#dcffb1}.chip.pink{background:#533044;color:#ffcae1}.chip.amber{background:#5a472b;color:#ffe0a0}
.feature-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:var(--space-md)}.feature{display:flex;flex-direction:column;min-height:235px}.feature .feature-icon{width:42px;height:42px;display:grid;place-items:center;border-radius:14px;background:var(--lime);color:#182115;font-weight:900;margin-bottom:16px;box-shadow:4px 5px 0 #6f4c74}.feature h2{font-size:19px}.feature p{color:var(--muted);margin:8px 0 18px}.feature .button,.feature a.button{margin-top:auto;text-decoration:none;text-align:center}
.form{display:grid;gap:11px}.form-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.field{display:grid;gap:6px}.field label{font-size:11px;font-weight:750;color:#d7cadf}.field input,.field select,.field textarea{width:100%;border:1px solid #554566;border-radius:11px;background:#151220;color:var(--ink);padding:10px 11px}.field textarea{min-height:92px;resize:vertical}.field small{color:var(--muted)}
.empty{display:grid;place-items:center;text-align:center;min-height:140px;padding:24px;border:1px dashed #594869;border-radius:14px;color:var(--muted)}.empty b{display:block;color:var(--ink);font-size:15px;margin-bottom:4px}.skeleton{position:relative;overflow:hidden;min-height:120px;border-radius:14px;background:#1d182b}.skeleton:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent,#fff1,transparent);animation:scan 1.2s infinite}@keyframes scan{from{transform:translateX(-100%)}to{transform:translateX(100%)}}
.progress{height:7px;background:#15121f;border-radius:99px;overflow:hidden;margin-top:8px}.progress span{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--pink),var(--lime));transform-origin:left;animation:grow .45s var(--ease)}@keyframes grow{from{transform:scaleX(0)}}
.text-block{white-space:pre-wrap;color:#d8ccdf;background:#15121f;border-radius:12px;padding:13px;max-height:240px;overflow:auto;font-size:12px}.approval-banner{display:flex;align-items:center;gap:14px;padding:15px;border-radius:14px;background:#3b2b20;border:1px solid #6b5136}.approval-banner strong{color:var(--amber)}
.settings-grid{display:grid;grid-template-columns:180px minmax(0,1fr) 280px;gap:14px;align-items:start}.settings-nav{position:sticky;top:18px;display:grid;gap:7px}.settings-nav button{border:1px solid var(--line);background:#181425;color:var(--muted);border-radius:12px;padding:11px;text-align:left;cursor:pointer}.settings-nav button.active,.settings-nav button:hover{background:#30253e;color:var(--ink);border-color:#836898}.settings-main,.settings-side{display:grid;gap:14px}.settings-card{border:1px solid var(--line);border-radius:16px;background:linear-gradient(140deg,#251d37,#181426);padding:17px}.settings-card h2{margin:0 0 5px;font-size:17px}.settings-card .sub{color:var(--muted);font-size:12px;margin:0 0 14px}.settings-state{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:11px}.settings-state.ok{color:var(--lime)}.settings-state.warn{color:var(--amber)}.settings-state.bad{color:var(--red)}.route-table{display:grid;gap:8px}.route-row{display:grid;grid-template-columns:minmax(120px,1.2fr) minmax(120px,1fr) auto;align-items:center;gap:9px;padding:10px 11px;border:1px solid #443752;border-radius:11px;background:#171323}.route-row b{font-size:12px}.route-row small{color:var(--muted)}.route-row select{width:100%;background:#13101d;color:var(--ink);border:1px solid #554566;border-radius:8px;padding:7px}.usage-hero{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.usage-hero .metric{padding:12px;border-radius:12px;background:#171323;border:1px solid #443752}.metric strong{display:block;font-size:19px;color:var(--lime)}.metric span{font-size:11px;color:var(--muted)}.usage-list{display:grid;gap:7px}.usage-line{display:grid;grid-template-columns:1.2fr .7fr .8fr;gap:8px;align-items:center;padding:8px 0;border-bottom:1px solid #30263d;font-size:12px}.usage-line:last-child{border-bottom:0}.usage-bar{height:6px;background:#31273e;border-radius:99px;overflow:hidden}.usage-bar i{display:block;height:100%;background:linear-gradient(90deg,var(--pink),var(--lime));border-radius:inherit}.change-summary{position:sticky;top:18px}.change-summary .diff{display:grid;gap:8px;max-height:300px;overflow:auto}.diff-line{padding:9px;border-radius:9px;background:#171323;border-left:3px solid var(--amber);font-size:11px}.preset-row{display:flex;flex-wrap:wrap;gap:7px}.preset-row button{font-size:11px}.settings-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.settings-help{padding:10px;border-radius:10px;background:#2a2138;color:#cdbfda;font-size:11px}.settings-help b{color:var(--lime)}
.scrim{display:none;position:fixed;inset:0;background:#080610b8;z-index:var(--z-scrim);backdrop-filter:blur(3px)}
.toast{position:fixed;right:20px;bottom:20px;z-index:var(--z-toast);max-width:min(430px,calc(100vw - 28px));padding:13px 16px;border-radius:14px;background:var(--paper);color:var(--paper-ink);font-weight:750;box-shadow:8px 9px 0 #765079;opacity:0;transform:translateY(24px);pointer-events:none;transition:.25s var(--ease)}.toast.show{opacity:1;transform:none}.toast.error{background:#ffd9df;box-shadow:8px 9px 0 #763449}
.mobile-title{display:none}
@media (max-width:1120px){.summary-strip{grid-template-columns:repeat(3,1fr)}.workspace{grid-template-columns:1fr}.feed{max-height:460px}}
@media (max-width:860px){
  .app{padding:14px}.topline,.updated{display:none}.hamburger{display:grid}.layout{grid-template-columns:1fr}.sidebar{position:fixed;left:12px;top:76px;bottom:12px;width:min(300px,calc(100vw - 44px));overflow:auto;z-index:var(--z-nav);transform:translateX(calc(-100% - 30px));opacity:0;pointer-events:none;transition:opacity .22s var(--ease)}.sidebar.open{transform:none;opacity:1;pointer-events:auto}.scrim.show{display:block}.mobile-title{display:block}.hero{grid-template-columns:auto 1fr}.hero-actions{grid-column:1/-1;justify-content:flex-start}.summary-strip{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:560px){.brand span,.top-actions>.button.primary{display:none}.brand-mark{width:46px;height:46px}.hero{grid-template-columns:1fr}.life-core{width:68px;height:68px}.summary-strip{grid-template-columns:1fr 1fr}.signal{padding:13px}.signal .value{font-size:17px}.module-grid,.feature-grid{grid-template-columns:1fr}.form-row{grid-template-columns:1fr}.section-head{align-items:flex-start;flex-direction:column}.item{flex-direction:column}.item-actions{justify-content:flex-start}}
@media (prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
</style>
</head>
<body>
<!-- compatibility markers: Anima 控制台 .map(p=>api(p)) id=draftRequest id=calendarCancelId id=skillId skill-drafts/ approveEngineeringTask 工程作用 id=moduleStatus module-grid body:before @keyframes drift prefers-reduced-motion hamburger toggleNav aria-expanded aria-controls="sidebar" id=scrim viewIn aria-live="polite" -->
<main class="app">
  <header class="topbar">
    <button id="hamburger" class="button hamburger" aria-label="打开导航" aria-expanded="false" aria-controls="sidebar">☰</button>
    <div class="brand"><span class="brand-mark">H</span><div><strong>Anima</strong><span>哈基米生命控制台 · Owner</span></div></div>
    <div class="topline"></div>
    <div class="top-actions"><span id="updated" class="updated">正在建立连接…</span><button id="refresh" class="button primary">同步全部状态</button></div>
  </header>
  <div class="layout">
    <nav id="sidebar" class="sidebar" aria-label="生命控制台导航">
      <div class="nav-title">life system / navigation</div>
      <button class="nav-button active" data-view="overview"><span class="index">01</span>现在怎么样</button>
      <button class="nav-button" data-view="conversation"><span class="index">02</span>对话与记忆</button>
      <button class="nav-button" data-view="cognition"><span class="index">03</span>认知与人格</button>
      <button class="nav-button" data-view="abilities"><span class="index">04</span>能力与自动化</button>
      <button class="nav-button" data-view="engineering"><span class="index">05</span>审批与工程</button>
      <button class="nav-button" data-view="settings"><span class="index">06</span>设置与权限</button>
      <div class="nav-foot"><b id="navState">正在感知系统</b><span>这里显示原因和动作，不展示接口原始数据。</span></div>
    </nav>
    <section class="content">
      <section id="overview" class="view active">
        <article class="hero"><div class="life-core">H</div><div><span class="eyebrow">living status</span><h1 id="heroTitle">正在确认哈基米的状态</h1><p id="heroText">正在检查 QQ、LLM、记忆与自主心跳是否协同运行。</p></div><div class="hero-actions"><button class="button" data-jump="timeline">看最近发生了什么</button><button id="heroRefresh" class="button primary">重新感知</button></div></article>
        <div id="summary" class="summary-strip" aria-live="polite"></div>
        <div class="workspace">
          <section class="panel"><div class="panel-head"><div><span class="eyebrow">whole system</span><h2>模块协同状态</h2></div><span id="moduleSummary" class="panel-note">正在读取…</span></div><div id="moduleStatus" class="module-grid"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div></section>
          <section class="panel"><div class="panel-head"><div><span class="eyebrow">recent moments</span><h2>最近动态</h2></div></div><div id="timeline" class="feed"><div class="skeleton"></div></div></section>
        </div>
      </section>

      <section id="conversation" class="view">
        <header class="section-head"><div><span class="eyebrow">continuity</span><h1>她正在经历什么</h1><p>把短期对话、时间感、生活痕迹和关系连续性组合成可理解的主体状态。</p></div></header>
        <div class="workspace"><div><section class="panel"><div class="panel-head"><h2>此刻的主体感</h2><span class="panel-note">时间、欲望与在场感</span></div><div id="subject" class="stack"><div class="skeleton"></div></div></section><section class="panel"><div class="panel-head"><h2>生活留下的痕迹</h2><span class="panel-note">日记与自我笔记只显示摘要</span></div><div id="life" class="stack"><div class="skeleton"></div></div></section></div><aside class="panel panel-accent"><span class="eyebrow">memory boundary</span><h2>记忆边界</h2><p class="panel-note">群聊按“群号 + 用户 QQ”隔离，图片本体不进入对话记忆；跨群事实和群氛围走独立存储。</p><div id="memoryModule" class="stack" style="margin-top:16px"></div></aside></div>
      </section>

      <section id="cognition" class="view">
        <header class="section-head"><div><span class="eyebrow">inner world</span><h1>认知与人格</h1><p>看她的欲望强度、身份稳定性、关系与世界观状态，而不是阅读调试对象。</p></div><a href="/cognitive" class="button primary">打开深度认知台</a></header>
        <div id="cognitiveOverview" class="summary-strip"></div>
        <div class="workspace"><section class="panel"><div class="panel-head"><h2>当前欲望</h2><span class="panel-note">按强度排序</span></div><div id="desires" class="stack"><div class="skeleton"></div></div></section><section class="panel"><div class="panel-head"><h2>身份与行为边界</h2></div><div id="identity" class="stack"><div class="skeleton"></div></div></section></div>
      </section>

      <section id="abilities" class="view">
        <header class="section-head"><div><span class="eyebrow">abilities & automation</span><h1>让她学会并持续做事</h1><p>Skills、订阅、日历和表情资产各自有明确入口、状态和审批边界。</p></div></header>
        <div class="feature-grid">
          <article class="panel feature"><span class="feature-icon">S</span><h2>已安装 Skills</h2><p>声明式受控能力，可以被对话和工具链调用。</p><div id="skills" class="stack"></div></article>
          <article class="panel feature"><span class="feature-icon">+</span><h2>让她学习新能力</h2><p>描述需求后只生成待审草案，不会自动安装。</p><form id="draftForm" class="form"><div class="field"><label for="draftRequest">你希望她学会什么</label><textarea id="draftRequest" placeholder="例如：检查某个公开网站是否正常，并告诉我页面标题" required></textarea><small>会经过静态验证、预览和 Owner 审批。</small></div><button class="button primary" type="submit">生成待审 Skill 草案</button></form></article>
          <article class="panel feature"><span class="feature-icon">表</span><h2>表情资产工作室</h2><p id="stickerSummary">审核池、图库、分类、语义选图和 LLM/VLM 重审。</p><a class="button primary" href="/stickers">管理表情资产</a></article>
        </div>
        <section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2>待审 Skill 草案</h2><span class="panel-note">先预览，再批准或驳回</span></div></div><div id="skillDrafts" class="stack"></div></section>
        <div class="workspace" style="margin-top:16px">
          <section class="panel"><div class="panel-head"><h2>订阅通知</h2><span class="panel-note">B 站开播或公开网页状态</span></div><form id="subscriptionForm" class="form"><div class="form-row"><div class="field"><label for="subPlatform">服务类型</label><select id="subPlatform"><option value="bilibili_live">B 站开播</option><option value="http_page">公开网页状态</option></select></div><div class="field"><label for="subSubject">直播间号或 HTTPS 地址</label><input id="subSubject" required placeholder="123456 或 https://example.com/status"></div></div><div class="field"><label for="subGroups">通知到哪些 QQ 群</label><input id="subGroups" required placeholder="727631526，多个群用逗号分隔"></div><button class="button primary" type="submit">创建订阅</button></form><div id="subscriptions" class="stack" style="margin-top:16px"></div></section>
          <section class="panel"><div class="panel-head"><h2>定时表达</h2><span class="panel-note">北京时间，先进入议程再决定发送</span></div><form id="calendarForm" class="form"><div class="form-row"><div class="field"><label for="calendarGroup">目标群</label><input id="calendarGroup" required inputmode="numeric" placeholder="727631526"></div><div class="field"><label for="calendarTime">每天几点</label><input id="calendarTime" required type="time" value="08:30"></div></div><div class="field"><label for="calendarText">想表达什么</label><input id="calendarText" required placeholder="例如：自然地向大家说早安"></div><button class="button primary" type="submit">添加每日计划</button></form><div id="calendar" class="stack" style="margin-top:16px"></div></section>
        </div>
      </section>

      <section id="engineering" class="view">
        <header class="section-head"><div><span class="eyebrow">approval boundary</span><h1>审批与工程</h1><p>代码完成不等于部署完成。工程作用、风险、测试和回滚证据必须在这里通过。</p></div></header>
        <div id="approvalCallout" class="approval-banner"><span>◆</span><div><strong>未经 Owner 批准，任何工程候选都不会安装或部署。</strong><div class="panel-note">批准、驳回和要求重做都会写入审计记录。</div></div></div>
        <div class="workspace" style="margin-top:16px"><section class="panel"><div class="panel-head"><h2>工程任务</h2><span id="taskCount" class="panel-note"></span></div><form id="taskForm" class="form"><div class="field"><label for="taskRequest">任务目标</label><textarea id="taskRequest" required placeholder="描述要诊断或完成的工程目标"></textarea></div><button class="button primary" type="submit">创建工程任务</button></form><div id="tasks" class="stack" style="margin-top:16px"></div></section><section class="panel"><div class="panel-head"><h2>高危动作审批</h2><span class="panel-note">参数只显示脱敏摘要</span></div><div id="approvals" class="stack"></div></section></div>
      </section>

      <section id="settings" class="view">
        <header class="section-head"><div><span class="eyebrow">life control center</span><h1>设置与权限</h1><p>用可读的控制项调整哈基米；每次改动先预览影响，密钥只显示是否已配置。</p></div><div class="settings-state" id="configState"><span class="status-dot warn"></span>正在读取设置</div></header>
        <div class="settings-grid">
          <nav class="settings-nav" aria-label="设置分类"><button class="active" data-settings-tab="llm">LLM 模型</button><button data-settings-tab="routes">模块路由</button><button data-settings-tab="usage">Token 用量</button><button data-settings-tab="behavior">主动行为</button><button data-settings-tab="permissions">权限与维护</button></nav>
          <div class="settings-main">
            <section class="settings-card settings-tab" data-settings-panel="llm"><h2>LLM 快速配置</h2><p class="sub">换模型前可先测试连接；应用后会生成变更记录，必要时受控重启。</p><form id="llmForm" class="form"><div class="form-row"><div class="field"><label for="llmProvider">提供商配置</label><select id="llmProvider"></select></div><div class="field"><label for="llmModel">默认模型</label><input id="llmModel" placeholder="gemini-3.1-pro-low"></div></div><div class="field"><label for="llmEndpoint">Base URL</label><input id="llmEndpoint" type="url" placeholder="https://gateway.example/v1"></div><div class="field"><label for="llmKey">API Key <small>留空保持原值</small></label><input id="llmKey" type="password" autocomplete="new-password" placeholder="已配置，不回显"></div><div class="form-row"><div class="field"><label for="llmTimeout">超时（秒）</label><input id="llmTimeout" type="number" min="5" max="300"></div><div class="field"><label for="llmRetries">重试次数</label><input id="llmRetries" type="number" min="0" max="4"></div></div><div class="settings-actions"><button class="button soft" type="button" id="llmTest">测试连接</button><button class="button primary" type="submit">生成变更预览</button></div></form><div class="settings-help" id="llmTestResult"><b>提示：</b>测试只访问 /models，不会替换当前工作连接。</div></section>
            <section class="settings-card settings-tab" data-settings-panel="routes" hidden><h2>模块模型路由</h2><p class="sub">单独指定模块模型；选择“继承默认”即可回到主模型。</p><div id="llmRoutes" class="route-table"><div class="skeleton"></div></div><div class="settings-actions"><button class="button primary" id="saveRoutes" type="button">生成路由变更</button></div></section>
            <section class="settings-card settings-tab" data-settings-panel="usage" hidden><div class="panel-head"><div><h2>Token 用量</h2><p class="sub">只统计元数据，不记录聊天正文；没有上游 usage 的调用会标记为估算。</p></div><select id="usageRange"><option value="today">今天</option><option value="7d">近 7 天</option><option value="30d">近 30 天</option></select></div><div id="usageHero" class="usage-hero"></div><div class="form-row" style="margin-top:16px"><div><h3>模型消耗</h3><div id="usageModels" class="usage-list"></div></div><div><h3>模块消耗</h3><div id="usageModules" class="usage-list"></div></div></div><div class="settings-actions"><button class="button soft" id="usageRefresh" type="button">刷新统计</button><a class="button" href="/api/llm/usage/export?format=csv" target="_blank">导出 CSV</a></div></section>
            <section class="settings-card settings-tab" data-settings-panel="behavior" hidden><h2>主动行为</h2><p class="sub">这些是绿色即时控制，不限制 LLM 用量，只控制群内打扰。</p><div id="autonomy" class="stack"><div class="skeleton"></div></div><div class="item-actions" style="justify-content:flex-start;margin-top:14px"><button class="button primary" data-autonomy="resume">恢复自主行为</button><button class="button danger" data-autonomy="pause">暂停自主行为</button></div></section>
            <section class="settings-card settings-tab" data-settings-panel="permissions" hidden><h2>权限与维护</h2><p class="sub">Owner 才能应用配置，管理员默认只读。</p><div id="permissions" class="stack"></div><form id="adminForm" class="form" style="margin-top:16px"><div class="field"><label for="adminQQ">添加管理员 QQ</label><input id="adminQQ" inputmode="numeric" required placeholder="输入 QQ 号"></div><button class="button primary" type="submit">添加管理员</button></form></section>
          </div>
          <aside class="settings-side"><section class="settings-card change-summary"><h2>本次修改</h2><p class="sub">还没有待应用的变更</p><div id="configDiff" class="diff"><div class="empty"><b>安全预览</b><span>修改表单后，这里会显示影响模块、风险和是否需要重启。</span></div></div><div class="settings-actions"><button class="button primary" id="applyConfig" type="button" disabled>通过并应用</button><button class="button danger" id="rollbackConfig" type="button" disabled>回滚</button></div></section><section class="settings-card"><h2>常用预设</h2><p class="sub">预设只填入表单，不会直接覆盖。</p><div id="configPresets" class="preset-row"></div></section></aside>
        </div>
      </section>
    </section>
  </div>
</main>
<div id="scrim" class="scrim"></div><aside id="toast" class="toast" role="status" aria-live="polite"></aside>
<script>
var state={modules:[],tasks:[],approvals:[],drafts:[],subscriptions:[],calendar:[],config:null,manifest:null,llmProviders:null,llmRoutes:null,usage:null,pendingChange:null};
function byId(id){return document.getElementById(id)}
function escapeHtml(value){return String(value==null?'':value).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function cookie(name){var found=document.cookie.split('; ').find(function(item){return item.indexOf(name+'=')===0});return found?decodeURIComponent(found.split('=').slice(1).join('=')):''}
function toast(message,error){var node=byId('toast');node.textContent=message;node.className='toast show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(function(){node.className='toast'},3800)}
async function api(path,options){options=options||{};options.headers=Object.assign({},options.headers||{}, {'X-Anima-CSRF':cookie('anima_webui_csrf')});var response=await fetch('/api/'+path,options);var body=await response.text(),data;try{data=JSON.parse(body)}catch(_){data=body}if(!response.ok)throw new Error(typeof data==='string'?data:(data.message||'请求没有成功'));return data}
async function mutate(path,method,body,success){try{var options={method:method||'POST'};if(body!==undefined){options.headers={'Content-Type':'application/json'};options.body=JSON.stringify(body)}await api(path,options);toast(success||'操作已完成');await refresh()}catch(error){toast(error.message,true)}}
function formatTime(value){if(!value)return '暂无时间';var date=new Date(typeof value==='number'?value*1000:value);return isNaN(date.getTime())?String(value):date.toLocaleString('zh-CN',{hour12:false})}
function relativeTime(value){if(!value)return '刚刚';var seconds=Math.max(0,Date.now()/1000-Number(value));if(seconds<60)return Math.floor(seconds)+' 秒前';if(seconds<3600)return Math.floor(seconds/60)+' 分钟前';if(seconds<86400)return Math.floor(seconds/3600)+' 小时前';return Math.floor(seconds/86400)+' 天前'}
var statusNames={running:'正常运行',ready:'已经就绪',degraded:'已降级',stopped:'未运行',disabled:'未启用',planned:'等待执行',awaiting_approval:'等待审批',completed:'已完成',failed:'失败',rejected:'已驳回',pending:'等待审批',approved:'已批准',expired:'已过期'};
var metricNames={channel_bound:'QQ 通道',channel_connected:'QQ 实时连接',events_received:'入站事件',outbound_successes:'出站成功',last_event_at:'最近入站',last_outbound_success_at:'最近出站',request_count:'LLM 请求',failure_count:'失败请求',last_status:'上游状态',sessions:'隔离会话',rounds:'对话轮次',messages:'记忆消息',recent_groups:'短时群上下文',embedding:'向量嵌入',rerank:'重排序',semantic:'语义检索',running:'循环运行',tick_sec:'心跳秒数',group_count:'已知群',agenda_pending:'待发表议程',daily_events:'每日计划',weekly_events:'每周计划',desires:'活跃欲望',relations:'关系档案',scars:'情感伤痕',world_entries:'世界条目',tool_count:'工具',loaded:'已装 Skills',invalid:'无效项',drafts:'草案',pending_review:'待审核',experience_records:'工具经历',learned_preferences:'经验规则',capabilities:'自生能力',users:'用户画像',groups:'群氛围',total:'总数',planned:'待执行',awaiting_approval:'待审批',completed:'已完成',failed:'失败',count:'资产总数',approved:'已批准',rejected:'已拒绝',fetch_fail_total:'取图失败',reconciled_missing:'已清理失效',chat_comprehension:'对话看图',memory_description:'描述进记忆',runtime_initialized:'运行时初始化',generated_today:'今日生图',daily_limit:'每日上限',subscriptions:'订阅数',enabled:'启用数',tasks:'工程任务',unlimited_daily_usage:'不限日用量',total_replies:'总回复',tool_calls:'工具调用',tool_failures:'工具失败',outbound_failures:'发送失败',repeated_replies:'重复回复',mode:'工作模式',recent_events:'近期事件'};
var eventNames={boot:'服务启动',message_received:'收到消息',message_sent:'已发送回复',agenda_created:'创建表达议程',image_generated:'完成一次生图',webui_task_approved:'工程任务已批准',webui_task_rejected:'工程任务已驳回',webui_sticker_approved:'表情资产已批准',webui_sticker_rejected:'表情资产已拒绝',subscription_created_from_webui:'创建订阅',calendar_event_created_from_webui:'创建每日计划',skill_draft_created:'生成 Skill 草案'};
function statusClass(value){return value==='running'?'':value==='ready'?'ready':value==='degraded'||value==='stopped'?'degraded':value==='disabled'?'disabled':'bad'}
function boolText(value){return value?'开启':'关闭'}
function metricValue(value){if(typeof value==='boolean')return boolText(value);if(value===0)return '0';if(typeof value==='number'&&value>1000000000)return relativeTime(value);return value==null||value===''?'—':String(value)}
function signal(label,value,hint,tone){return '<article class="signal"><span class="label"><i class="status-dot '+(tone||'')+'"></i>'+escapeHtml(label)+'</span><span class="value">'+escapeHtml(value)+'</span><span class="hint">'+escapeHtml(hint)+'</span></article>'}
function empty(title,description){return '<div class="empty"><div><b>'+escapeHtml(title)+'</b><span>'+escapeHtml(description)+'</span></div></div>'}
function moduleCard(item){var metrics=Object.entries(item.metrics||{}).filter(function(pair){return pair[1]!==null&&pair[1]!==undefined}).slice(0,7);return '<article class="module"><div class="module-top"><h3>'+escapeHtml(item.label)+'</h3><span class="state '+statusClass(item.status)+'">'+escapeHtml(statusNames[item.status]||item.status)+'</span></div><p>'+escapeHtml(item.message)+'</p><div class="metric-list">'+metrics.map(function(pair){return '<span class="metric-chip">'+escapeHtml(metricNames[pair[0]]||pair[0])+' <b>'+escapeHtml(metricValue(pair[1]))+'</b></span>'}).join('')+'</div></article>'}
function renderModules(data){state.modules=data.modules||[];var attention=state.modules.filter(function(item){return item.status==='degraded'||item.status==='stopped'});byId('moduleStatus').innerHTML=state.modules.map(moduleCard).join('')||empty('还没有模块状态','服务启动后会在这里出现。');byId('moduleSummary').textContent=attention.length?attention.length+' 个模块需要关注':state.modules.length+' 个模块协同正常';byId('navState').textContent=attention.length?'有 '+attention.length+' 项需要你看看':'系统整体自洽运行';var memory=state.modules.find(function(item){return item.id==='chat_memory'||item.id==='crossgroup'});byId('memoryModule').innerHTML=memory?moduleCard(memory):empty('记忆尚未初始化','第一轮有效对话后会建立记忆。')}
function renderTimeline(data){var items=(data&&data.events)||[];byId('timeline').innerHTML=items.length?items.slice(0,24).map(function(item,index){var name=eventNames[item.type]||String(item.type||'系统事件').replace(/_/g,' ');return '<article class="feed-item"><span class="feed-mark">'+String(index+1).padStart(2,'0')+'</span><div><b>'+escapeHtml(name)+'</b><p>'+escapeHtml(relativeTime(item.ts||item.time||item.at))+'</p></div></article>'}).join(''):empty('最近很安静','新的对话、自动化与审批事件会出现在这里。')}
function renderSubject(data){var desires=data.active_desires||[],presence=data.group_presence||[],sylann=data.sylann||{};byId('subject').innerHTML=signal('北京时间',new Date(data.local_time||Date.now()).toLocaleString('zh-CN',{hour12:false}),'她用这条时间轴理解相遇与等待')+signal('近期互动',String(data.recent_interactions||0),'有时间记录的关系')+signal('感知到的群',String(presence.length),'每个群保留独立氛围')+signal('Sylann',sylann.enabled?(sylann.active?'完整接入':'已启用'):'未启用',sylann.package_version?'底层 '+sylann.package_version:'认知适配状态')+(desires.length?'<div class="stack">'+desires.slice(0,4).map(function(item){return '<article class="item"><div class="item-main"><b>'+escapeHtml(item.content)+'</b><div class="progress"><span style="width:'+Math.round(Number(item.intensity||0)*100)+'%"></span></div></div><span class="chip pink">强度 '+Math.round(Number(item.intensity||0)*100)+'%</span></article>'}).join('')+'</div>':'')}
function renderLife(data){var diary=String(data.diary_tail||'').trim(),notes=String(data.notes_tail||'').trim();byId('life').innerHTML='<div class="summary-strip" style="grid-template-columns:repeat(3,1fr);margin:0">'+signal('世界记忆',String(data.world_entry_count||0),'长期理解条目')+signal('情感伤痕',String(data.scar_count||0),'会随时间淡化')+signal('待发表议程',String(data.agenda_pending||0),'等待合适时机')+'</div>'+(diary?'<div><span class="eyebrow">最近日记</span><div class="text-block">'+escapeHtml(diary.slice(-900))+'</div></div>':empty('还没有日记','生活模拟产生的片段会在这里留下摘要。'))+(notes?'<div><span class="eyebrow">自我笔记</span><div class="text-block">'+escapeHtml(notes.slice(-900))+'</div></div>':'')}
function renderCognition(overview,desires,identity){byId('cognitiveOverview').innerHTML=signal('身份稳定度',Math.round(Number(overview.identity_stability||0)*100)+'%','越高越稳定')+signal('活跃欲望',String(overview.desires||0),'当前驱动力')+signal('关系档案',String(overview.relations||0),'有连续性的关系')+signal('矛盾线索',String(overview.contradictions||0),'等待自然澄清')+signal('人格提案',overview.persona_has_proposal?'等待审批':'没有待审修改','人格不会静默改变',overview.persona_has_proposal?'warn':'');var desireItems=(desires&&desires.items)||[];byId('desires').innerHTML=desireItems.length?desireItems.map(function(item){return '<article class="item"><div class="item-main"><b>'+escapeHtml(item.content)+'</b><p>存在 '+Math.max(0,Math.floor(Number(item.age_seconds||0)/60))+' 分钟</p><div class="progress"><span style="width:'+Math.round(Number(item.intensity||0)*100)+'%"></span></div></div><span class="chip pink">'+Math.round(Number(item.intensity||0)*100)+'%</span></article>'}).join(''):empty('此刻没有强烈欲望','这不是故障，她可能处在平静阶段。');var behaviors=(identity&&identity.behaviors)||{};byId('identity').innerHTML=signal('身份稳定度',Math.round(Number(identity.stability||0)*100)+'%','人格一致性')+signal('主动信息收集',boolText(behaviors.active_info_collection),'受权限与安全边界约束')+signal('自主联网',boolText(behaviors.autonomous_web),'只读探查优先')+signal('核心变更',boolText(behaviors.core_mutation),'任何候选都需 Owner 审批')}
function renderSkills(data){var items=(data&&data.items)||[];byId('skills').innerHTML=items.length?items.slice(0,8).map(function(item){return '<article class="item"><div class="item-main"><b>'+escapeHtml(item.name||item.id)+'</b><p>'+escapeHtml(item.description||'受控声明式能力')+'</p></div><span class="chip lime">'+escapeHtml(item.min_level||'受控')+'</span></article>'}).join(''):empty('还没有已安装 Skill','可以在旁边描述需求，先生成待审草案。')}
function readableDraftRequest(item){var request=String(item.request||''),marks=(request.match(/\?/g)||[]).length;if(marks>=4&&marks/Math.max(1,request.length)>.2)return (item.manifest&&item.manifest.description)||'历史草案的原始需求文本在旧版本中损坏，已用能力说明代替。';return request||'Skill 草案'}
function renderDrafts(data){state.drafts=(data&&data.items)||[];byId('skillDrafts').innerHTML=state.drafts.length?state.drafts.slice().reverse().slice(0,16).map(function(item){var pending=item.status==='pending_review',request=readableDraftRequest(item);return '<article class="item"><div class="item-main"><b>'+escapeHtml((item.manifest&&item.manifest.name)||request||item.id)+'</b><p>'+escapeHtml(request)+'</p><div class="chips"><span class="chip '+(pending?'amber':'')+'">'+escapeHtml(statusNames[item.status]||item.status)+'</span>'+(item.errors&&item.errors.length?'<span class="chip">'+item.errors.length+' 个验证问题</span>':'')+'</div></div>'+(pending?'<div class="item-actions"><button class="button small" data-draft="preview" data-id="'+escapeHtml(item.id)+'">先预览</button><button class="button primary small" data-draft="approve" data-id="'+escapeHtml(item.id)+'">批准安装</button><button class="button danger small" data-draft="reject" data-id="'+escapeHtml(item.id)+'">驳回</button></div>':'')+'</article>'}).join(''):empty('没有待审 Skill','新草案会出现在这里。');bindDynamicActions()}
function renderSubscriptions(data){state.subscriptions=(data&&data.items)||[];byId('subscriptions').innerHTML=state.subscriptions.length?state.subscriptions.map(function(item){return '<article class="item"><div class="item-main"><b>'+(item.platform==='bilibili_live'?'B 站直播间 ':'网页状态 ')+escapeHtml(item.subject_id)+'</b><p>通知群：'+escapeHtml((item.target_groups||[]).join('、')||'未设置')+' · 当前 '+escapeHtml(item.last_state||'尚未轮询')+'</p></div><button class="button danger small" data-delete-sub="'+escapeHtml(item.id)+'">删除订阅</button></article>'}).join(''):empty('还没有订阅','创建后会按周期检查，并只在状态变化时通知。');bindDynamicActions()}
function renderCalendar(data){var items=[].concat(data.items||[],data.weekly_items||[]).filter(function(item){return item.enabled});state.calendar=items;byId('calendar').innerHTML=items.length?items.map(function(item){var schedule=item.weekday?'每周 '+['','一','二','三','四','五','六','日'][item.weekday]:'每天';return '<article class="item"><div class="item-main"><b>'+schedule+' '+String(item.hour).padStart(2,'0')+':'+String(item.minute).padStart(2,'0')+'</b><p>群 '+escapeHtml(item.group_id)+' · '+escapeHtml(item.text)+'</p></div><button id="calendarCancelId" class="button danger small" data-delete-calendar="'+escapeHtml(item.id)+'">取消</button></article>'}).join(''):empty('没有定时计划','添加后会先形成表达议程，不会绕过主动发言控制。');bindDynamicActions()}
function proposalSummary(item){var proposal=item.proposal||{};var parts=[];if(proposal.purpose||proposal.effect)parts.push('<p><b>工程作用：</b>'+escapeHtml(proposal.purpose||proposal.effect)+'</p>');if(proposal.risk)parts.push('<p><b>风险：</b>'+escapeHtml(proposal.risk)+'</p>');if(proposal.tests)parts.push('<p><b>测试：</b>'+escapeHtml(Array.isArray(proposal.tests)?proposal.tests.join('；'):proposal.tests)+'</p>');if(proposal.files)parts.push('<p><b>影响文件：</b>'+escapeHtml(Array.isArray(proposal.files)?proposal.files.join('、'):proposal.files)+'</p>');return parts.join('')}
function renderTasks(data){state.tasks=(data&&data.items)||[];byId('taskCount').textContent=(data&&data.total||state.tasks.length)+' 个任务';byId('tasks').innerHTML=state.tasks.length?state.tasks.map(function(item){var waiting=item.status==='awaiting_approval',planned=item.status==='planned';return '<article class="item"><div class="item-main"><b>'+escapeHtml(item.request)+'</b><p>'+escapeHtml(item.kind||'工程任务')+' · '+formatTime(item.updated_at||item.created_at)+'</p>'+proposalSummary(item)+(item.evidence&&item.evidence.length?'<div class="chips"><span class="chip">'+item.evidence.length+' 条证据</span></div>':'')+'<div class="chips"><span class="chip '+(waiting?'amber':'')+'">'+escapeHtml(statusNames[item.status]||item.status)+'</span></div></div><div class="item-actions">'+(planned?'<button class="button primary small" data-task="execute" data-id="'+item.id+'">开始执行</button>':'')+(waiting?'<button class="button primary small" data-task="approve" data-id="'+item.id+'">通过测试部署</button><button class="button small" data-task="redo" data-id="'+item.id+'">要求重做</button><button class="button danger small" data-task="reject" data-id="'+item.id+'">驳回</button>':'')+'</div></article>'}).join(''):empty('还没有工程任务','创建后由任务代理先收集证据，再进入审批。');bindDynamicActions()}
function renderApprovals(data){state.approvals=(data&&data.items)||[];var pending=state.approvals.filter(function(item){return item.status==='pending'});byId('approvals').innerHTML=pending.length?pending.map(function(item){return '<article class="item"><div class="item-main"><b>'+escapeHtml(item.tool)+'</b><p>参数摘要 '+escapeHtml(item.args_digest)+' · '+formatTime(item.created_at)+'</p></div><div class="item-actions"><button class="button primary small" data-approval="approve" data-id="'+item.id+'">批准并执行</button><button class="button danger small" data-approval="reject" data-id="'+item.id+'">拒绝</button></div></article>'}).join(''):empty('没有高危动作等待','当前所有工具动作都在安全边界内。');bindDynamicActions()}
function renderPermissions(data){var owners=data.owners||[],admins=data.admins||[];byId('permissions').innerHTML='<div><span class="eyebrow">Owners</span><div class="chips">'+owners.map(function(qq){return '<span class="chip lime">QQ '+escapeHtml(qq)+'</span>'}).join('')+'</div></div><div><span class="eyebrow">Administrators</span>'+(admins.length?'<div class="stack">'+admins.map(function(qq){return '<article class="item"><b>QQ '+escapeHtml(qq)+'</b><button class="button danger small" data-remove-admin="'+escapeHtml(qq)+'">移除管理员</button></article>'}).join('')+'</div>':empty('没有额外管理员','只有 Owner 拥有最高权限。'))+'</div>';bindDynamicActions()}
function renderAutonomy(data){byId('autonomy').innerHTML=signal('自主心跳',data.running?'正在运行':'已停止',data.enabled?'主动行为总开关已开启':'主动行为总开关已暂停',data.running?'':'warn')+signal('主动发言概率',Math.round(Number(data.active_reply_prob||0)*100)+'%','命中后仍经过群冷却和上下文判断')+signal('单群每日上限',String(data.daily_max_per_group||0),'控制打扰，不限制 LLM 用量')+signal('已知群',String(data.groups_known||0),'来自真实 QQ 观察')+(data.self_improve_running?'<div class="approval-banner"><strong>工程代理正在处理一个候选</strong></div>':'')}
function renderLLMConfig(config,providers){state.config=config||{};state.llmProviders=providers||{};var s=(config&&config.state)||{};var llm=s.llm||{};var select=byId('llmProvider');if(select){var items=(providers&&providers.providers)||[];select.innerHTML=items.map(function(p){return '<option value="'+escapeHtml(p.id)+'" '+(p.id===(providers&&providers.active)?'selected':'')+'>'+escapeHtml(p.label||p.id)+(p.configured?' · 已配置':' · 未配置')+'</option>'}).join('');}if(byId('llmModel'))byId('llmModel').value=llm.model||'';if(byId('llmEndpoint'))byId('llmEndpoint').value=llm.endpoint||'';if(byId('llmTimeout'))byId('llmTimeout').value=llm.timeout||60;if(byId('llmRetries'))byId('llmRetries').value=llm.retries||0;var status=byId('configState');if(status){status.className='settings-state ok';status.innerHTML='<span class="status-dot"></span>配置已加载 · '+escapeHtml(llm.active_provider||'default')}}
function renderRoutes(data){state.llmRoutes=data||{};var node=byId('llmRoutes');if(!node)return;var routes=(data&&data.routes)||[];var defaultModel=(data&&data.default_model)||'';var models=((state.llmProviders&&state.llmProviders.providers)||[]).reduce(function(all,p){return all.concat(p.models||[]);},[]);var options=models.concat([defaultModel]).filter(Boolean).filter(function(x,i,a){return a.indexOf(x)===i}).map(function(x){return '<option value="'+escapeHtml(x)+'"></option>'}).join('');var rows=routes.map(function(row){return '<div class="route-row"><div><b>'+escapeHtml(row.label)+'</b><small>'+((row.usage&&row.usage.calls)||0)+' 次 · '+Number((row.usage&&row.usage.total_tokens)||0).toLocaleString()+' Token</small></div><input list="llmModelChoices" data-route="'+escapeHtml(row.id)+'" value="'+escapeHtml(row.inherited?'':row.model)+'" placeholder="继承默认 · '+escapeHtml(defaultModel)+'"><span class="chip '+(row.inherited?'':'lime')+'">'+(row.inherited?'继承':'独立')+'</span></div>'}).join('');node.innerHTML=rows?(rows+'<datalist id="llmModelChoices">'+options+'</datalist>'):empty('暂无模块路由','服务启动后会显示可独立切换模型的模块。')}
function renderUsage(data){state.usage=data||{};var hero=byId('usageHero');if(!hero)return;hero.innerHTML='<div class="metric"><strong>'+Number(data.total_tokens||0).toLocaleString()+'</strong><span>总 Token</span></div><div class="metric"><strong>'+Number(data.calls||0).toLocaleString()+'</strong><span>调用次数</span></div><div class="metric"><strong>'+Number(data.failures||0).toLocaleString()+'</strong><span>失败次数</span></div><div class="metric"><strong>'+Math.round(Number(data.p95_latency_ms||0))+' ms</strong><span>P95 延迟 · '+Number(data.estimated_calls||0)+' 次估算</span></div>';var max=Math.max.apply(null,(data.models||[]).map(function(x){return Number(x.total_tokens||0)}).concat([1]));byId('usageModels').innerHTML=(data.models||[]).slice(0,8).map(function(x){return '<div class="usage-line"><span>'+escapeHtml(x.model||'unknown')+'</span><span>'+Number(x.total_tokens||0).toLocaleString()+'</span><div class="usage-bar"><i style="width:'+Math.round(Number(x.total_tokens||0)/max*100)+'%"></i></div></div>'}).join('')||empty('今天还没有调用记录','当 bot 开始工作后，这里会按模型统计。');var maxModule=Math.max.apply(null,(data.modules||[]).map(function(x){return Number(x.total_tokens||0)}).concat([1]));byId('usageModules').innerHTML=(data.modules||[]).slice(0,8).map(function(x){return '<div class="usage-line"><span>'+escapeHtml(x.module||'unknown')+'</span><span>'+Number(x.total_tokens||0).toLocaleString()+'</span><div class="usage-bar"><i style="width:'+Math.round(Number(x.total_tokens||0)/maxModule*100)+'%"></i></div></div>'}).join('')||empty('还没有模块用量','模块身份会随调用一起记录。')}
function renderChange(item){state.pendingChange=item;var box=byId('configDiff');if(!box)return;if(!item){box.innerHTML='<div class="empty"><b>安全预览</b><span>修改表单后，这里会显示影响模块、风险和是否需要重启。</span></div>';byId('applyConfig').disabled=true;byId('rollbackConfig').disabled=true;return}box.innerHTML='<div class="diff-line"><b>'+escapeHtml(item.id)+'</b><br>风险：'+escapeHtml(item.risk)+' · '+(item.restart_required?'需要重启':'可即时生效')+'<br>影响：'+escapeHtml((item.impact||[]).join('、')||'配置本身')+'</div><div class="diff-line">已通过 Pydantic 校验，应用前仍可继续修改。</div>';byId('applyConfig').disabled=false;byId('rollbackConfig').disabled=true}
function llmFormPatch(){var llm={endpoint:byId('llmEndpoint').value.trim(),model:byId('llmModel').value.trim(),timeout:Number(byId('llmTimeout').value||60),retries:Number(byId('llmRetries').value||0)};var key=byId('llmKey').value.trim();if(key)llm.api_key=key;var provider=byId('llmProvider').value;if(provider)llm.active_provider=provider;return {llm:llm}}
async function submitConfigPatch(patch){try{var item=await api('config/change-sets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({patch:patch})});renderChange(item);toast('变更已生成，请在右侧确认影响后应用')}catch(error){toast(error.message,true)}}
async function loadSettings(){try{var values=await Promise.all([api('config/state'),api('llm/providers'),api('llm/routes'),api('llm/usage?range=today'),api('config/manifest')]);renderLLMConfig(values[0],values[1]);renderRoutes(values[2]);renderUsage(values[3]);state.manifest=values[4];var preset=byId('configPresets');if(preset)preset.innerHTML=(state.manifest.presets||[]).map(function(x){return '<button class="button small" data-preset="'+escapeHtml(x.id)+'">'+escapeHtml(x.label)+'</button>'}).join('');bindSettingsActions();bindRouteSave()}catch(error){var node=byId('configState');if(node){node.className='settings-state bad';node.innerHTML='<span class="status-dot bad"></span>设置读取失败'}toast('设置中心读取失败：'+error.message,true)}}
function bindRouteSave(){var button=byId('saveRoutes');if(!button||button.dataset.bound)return;button.dataset.bound='1';button.onclick=function(){var routes={};document.querySelectorAll('[data-route]').forEach(function(input){routes[input.dataset.route]=input.value.trim()});submitConfigPatch({llm:{module_models:routes}})}}
function bindSettingsActions(){document.querySelectorAll('[data-settings-tab]').forEach(function(button){if(button.dataset.bound)return;button.dataset.bound='1';button.onclick=function(){document.querySelectorAll('[data-settings-tab]').forEach(function(x){x.classList.toggle('active',x===button)});document.querySelectorAll('[data-settings-panel]').forEach(function(x){x.hidden=x.dataset.settingsPanel!==button.dataset.settingsTab})}});var form=byId('llmForm');if(form&&!form.dataset.bound){form.dataset.bound='1';form.onsubmit=function(e){e.preventDefault();submitConfigPatch(llmFormPatch())}}var test=byId('llmTest');if(test&&!test.dataset.bound){test.dataset.bound='1';test.onclick=async function(){var n=byId('llmTestResult');n.innerHTML='<b>正在测试：</b>连接模型网关…';try{var p=llmFormPatch().llm;var result=await api('llm/providers/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});n.innerHTML=result.ok?'<b>连接成功：</b>'+Number(result.models&&result.models.length||0)+' 个模型，'+result.latency_ms+' ms':'<b>连接失败：</b>'+escapeHtml(result.message||('HTTP '+result.status));n.className='settings-help '+(result.ok?'':'error')}catch(error){n.innerHTML='<b>测试失败：</b>'+escapeHtml(error.message)}}}var apply=byId('applyConfig');if(apply&&!apply.dataset.bound){apply.dataset.bound='1';apply.onclick=async function(){if(!state.pendingChange)return;try{var result=await api('config/change-sets/'+state.pendingChange.id+'/apply',{method:'POST'});toast(result.restart_scheduled?'配置已应用，服务将受控重启':'配置已应用');renderChange(null);loadSettings()}catch(error){toast(error.message,true)}}}var range=byId('usageRange');if(range&&!range.dataset.bound){range.dataset.bound='1';range.onchange=async function(){renderUsage(await api('llm/usage?range='+encodeURIComponent(range.value)))}}var usageRefresh=byId('usageRefresh');if(usageRefresh&&!usageRefresh.dataset.bound){usageRefresh.dataset.bound='1';usageRefresh.onclick=function(){loadSettings()}}document.querySelectorAll('[data-preset]').forEach(function(button){if(button.dataset.bound)return;button.dataset.bound='1';button.onclick=function(){var item=(state.manifest.presets||[]).find(function(x){return x.id===button.dataset.preset});if(item&&item.patch){if(item.patch.autonomy){Object.keys(item.patch.autonomy).forEach(function(k){var input=byId(k==='active_reply_prob'?'llmModel':null);});}toast('已载入预设差异，请到主动行为页确认并生成变更')}}})}
function updateHero(health,modules,stickers,autonomy){var trouble=(modules.modules||[]).filter(function(item){return item.status==='degraded'||item.status==='stopped'});var awake=health.running,qq=health.channel_connected===undefined?health.channel_bound:health.channel_connected,llm=health.llm&&!health.llm.last_error;byId('heroTitle').textContent=awake&&qq&&llm?'哈基米正在清醒地生活':awake?'哈基米醒着，但有事情需要你看看':'哈基米当前没有运行';byId('heroText').textContent=!awake?'核心服务没有报告运行状态。':!qq?'核心服务正常，但 QQ WebSocket 还没有连接，当前不能收发消息。':!llm?'QQ 已连接，但语言模型最近一次请求需要检查。':trouble.length?'QQ 与 LLM 正常，另有 '+trouble.length+' 个非核心模块处于降级或停止状态。':'QQ、LLM、记忆、认知与自主心跳正在协同工作。';byId('summary').innerHTML=signal('核心服务',awake?'在线':'离线',awake?'进程正常响应':'需要检查服务',awake?'':'bad')+signal('QQ 通道',qq?'实时在线':'未连接',qq?'NapCat WebSocket 可收发':'当前不能收发 QQ 消息',qq?'':'warn')+signal('LLM',llm?'可用':'需检查',llm?'最近请求正常':'查看语言模型状态',llm?'':'warn')+signal('自主行为',autonomy.enabled?'已开启':'已暂停',autonomy.running?'心跳正在运行':'不会主动发言',autonomy.enabled?'':'warn')+signal('表情资产',String((stickers.stats&&stickers.stats.count)||0)+' 张',((stickers.stats&&stickers.stats.pending_review)||0)+' 张待审核')}
async function refresh(){byId('updated').textContent='正在同步全部状态…';var endpoints={health:'health',modules:'modules/status',timeline:'timeline?limit=40',subject:'subject',life:'life',overview:'cognitive/overview',desires:'cognitive/desires',identity:'cognitive/identity',skills:'skills',drafts:'skill-drafts',subscriptions:'subscriptions',calendar:'calendar',stickers:'stickers',tasks:'tasks?page=1&page_size=40',approvals:'approvals?page=1&page_size=40',permissions:'permissions',autonomy:'autonomy/status'};var entries=Object.entries(endpoints),results=await Promise.allSettled(entries.map(function(pair){return api(pair[1])})),data={},failed=[];results.forEach(function(result,index){var key=entries[index][0];if(result.status==='fulfilled')data[key]=result.value;else failed.push({key:key,error:result.reason})});if(data.modules)renderModules(data.modules);if(data.timeline)renderTimeline(data.timeline);if(data.subject)renderSubject(data.subject);if(data.life)renderLife(data.life);if(data.overview&&data.desires&&data.identity)renderCognition(data.overview,data.desires,data.identity);if(data.skills)renderSkills(data.skills);if(data.drafts)renderDrafts(data.drafts);if(data.subscriptions)renderSubscriptions(data.subscriptions);if(data.calendar)renderCalendar(data.calendar);if(data.stickers){byId('stickerSummary').textContent='共 '+(data.stickers.stats.count||0)+' 张，'+(data.stickers.stats.pending_review||0)+' 张等待审核。审核池、图库、语义选图和 LLM/VLM 重审都在独立工作室。'}if(data.tasks)renderTasks(data.tasks);if(data.approvals)renderApprovals(data.approvals);if(data.permissions)renderPermissions(data.permissions);if(data.autonomy)renderAutonomy(data.autonomy);if(data.health&&data.modules&&data.stickers&&data.autonomy)updateHero(data.health,data.modules,data.stickers,data.autonomy);byId('updated').textContent=failed.length?'部分数据未更新 · '+failed.map(function(item){return item.key}).join('、'):'已同步 · '+new Date().toLocaleTimeString('zh-CN',{hour12:false});if(failed.length)toast('有 '+failed.length+' 个区域读取失败；其他功能仍可使用。',true)}
function bindDynamicActions(){document.querySelectorAll('[data-draft]').forEach(function(button){button.onclick=function(){mutate('skill-drafts/'+button.dataset.id+'/'+button.dataset.draft,'POST',undefined,button.dataset.draft==='approve'?'Skill 已批准并安装':'Skill 草案状态已更新')}});document.querySelectorAll('[data-delete-sub]').forEach(function(button){button.onclick=function(){if(confirm('删除这项订阅？之后不会再发送对应通知。'))mutate('subscriptions/'+button.dataset.deleteSub,'DELETE',undefined,'订阅已删除')}});document.querySelectorAll('[data-delete-calendar]').forEach(function(button){button.onclick=function(){if(confirm('取消这项定时计划？'))mutate('calendar/'+button.dataset.deleteCalendar,'DELETE',undefined,'定时计划已取消')}});document.querySelectorAll('[data-task]').forEach(function(button){button.onclick=function(){var action=button.dataset.task,body;if(action==='reject'||action==='redo'){var reason=prompt(action==='redo'?'请说明希望怎样重做：':'请说明驳回原因：');if(reason===null)return;body={reason:reason}}mutate('tasks/'+button.dataset.id+'/'+action,'POST',body,action==='approve'?'工程任务已批准':action==='execute'?'工程任务已开始执行':'工程任务状态已更新')}});document.querySelectorAll('[data-approval]').forEach(function(button){button.onclick=function(){mutate('approvals/'+button.dataset.id+'/'+button.dataset.approval,'POST',undefined,button.dataset.approval==='approve'?'动作已批准并执行':'动作已拒绝')}});document.querySelectorAll('[data-remove-admin]').forEach(function(button){button.onclick=function(){if(confirm('移除管理员 QQ '+button.dataset.removeAdmin+'？'))mutate('permissions/admins/'+button.dataset.removeAdmin,'DELETE',undefined,'管理员已移除')}})}
function openView(id){document.querySelectorAll('.nav-button').forEach(function(button){button.classList.toggle('active',button.dataset.view===id)});document.querySelectorAll('.view').forEach(function(view){view.classList.toggle('active',view.id===id)});closeNav();window.scrollTo({top:0,behavior:'smooth'})}
function toggleNav(){var nav=byId('sidebar'),open=!nav.classList.contains('open');nav.classList.toggle('open',open);byId('scrim').classList.toggle('show',open);byId('hamburger').setAttribute('aria-expanded',String(open))}
function closeNav(){byId('sidebar').classList.remove('open');byId('scrim').classList.remove('show');byId('hamburger').setAttribute('aria-expanded','false')}
document.querySelectorAll('.nav-button').forEach(function(button){button.addEventListener('click',function(){openView(button.dataset.view)})});byId('hamburger').onclick=toggleNav;byId('scrim').onclick=closeNav;byId('refresh').onclick=function(){toast('正在同步系统状态');refresh()};byId('heroRefresh').onclick=function(){byId('refresh').click()};document.querySelector('[data-jump="timeline"]').onclick=function(){byId('timeline').scrollIntoView({behavior:'smooth',block:'center'})};
byId('draftForm').onsubmit=function(event){event.preventDefault();mutate('skill-drafts','POST',{request:byId('draftRequest').value},'Skill 草案已生成，等待你预览和审批').then(function(){byId('draftRequest').value=''})};
byId('subscriptionForm').onsubmit=function(event){event.preventDefault();var groups=byId('subGroups').value.split(/[,，\s]+/).filter(Boolean).map(Number);mutate('subscriptions','POST',{platform:byId('subPlatform').value,subject_id:byId('subSubject').value,target_groups:groups},'订阅已创建')};
byId('calendarForm').onsubmit=function(event){event.preventDefault();mutate('calendar/daily','POST',{group_id:Number(byId('calendarGroup').value),time:byId('calendarTime').value,text:byId('calendarText').value},'每日计划已添加')};
byId('taskForm').onsubmit=function(event){event.preventDefault();mutate('tasks','POST',{request:byId('taskRequest').value},'工程任务已创建').then(function(){byId('taskRequest').value=''})};
byId('adminForm').onsubmit=function(event){event.preventDefault();mutate('permissions/admins','POST',{qq:Number(byId('adminQQ').value)},'管理员已添加').then(function(){byId('adminQQ').value=''})};
document.querySelectorAll('[data-autonomy]').forEach(function(button){button.onclick=function(){mutate('autonomy/'+button.dataset.autonomy,'POST',undefined,button.dataset.autonomy==='resume'?'自主行为已恢复':'自主行为已暂停')}});
refresh().catch(function(error){byId('updated').textContent='控制台读取失败';toast('控制台无法读取数据：'+error.message,true)});loadSettings();
</script>
</body>
</html>"""
